<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="documents documents--<?php echo esc_attr( $mode ); ?>" id="<?php echo esc_attr( $root_id ); ?>" aria-labelledby="<?php echo esc_attr( $title_id ); ?>"><div class="container"><div class="documents__panel">
  <h2 class="documents__title" id="<?php echo esc_attr( $title_id ); ?>"><?php echo esc_html( $section_data['title'] ?? '' ); ?></h2><div class="documents__intro"><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div>
  <div class="documents__cards" data-documents-slider tabindex="0"><?php foreach ( $items as $item ) : $file_url = platejka_section_file_url( $item['file'] ?? 0 ); ?><article class="document-card document-card--<?php echo esc_attr( $mode ); ?>"><?php echo platejka_section_image( $item['image'] ?? 0, 'medium', array( 'class' => 'document-card__preview', 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><div class="document-card__content"><h3><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php if ( ! empty( $item['caption'] ) ) : ?><span class="document-card__file"><?php echo esc_html( $item['caption'] ); ?></span><?php endif; ?></div><?php if ( $file_url ) : ?><a class="document-card__download" href="<?php echo esc_url( $file_url ); ?>" download><?php echo esc_html( $item['link']['title'] ?? __( 'Скачать', 'platejka_rework' ) ); ?></a><?php endif; ?></article><?php endforeach; ?></div>
</div></div></section>
